<script setup lang="ts">
import { computed, reactive, ref } from 'vue';
import { useRouter } from 'vue-router';
import { ElMessage } from 'element-plus';
import type { Assignment, Capability, Mode, Order, Player, Tier } from '../../shared/types';
import { api, money, notifyError, exportFile } from '../lib/api';
import { state, refresh, can } from '../lib/store';
import PlayerGender from '../components/PlayerGender.vue';

const router = useRouter();
const modes: Mode[] = ['机密', '绝密'];
const tiers: Tier[] = ['娱乐陪', '技术陪', '高阶陪', '明星陪', '本月置顶明星'];
const search = ref('');
const statusFilter = ref('');
const modeFilter = ref('');
const tierFilter = ref('');
const editorOpen = ref(false);
const detailOpen = ref(false);
const detailId = ref('');
const detailTab = ref('capabilities');
const busy = ref(false);
const editing = ref<Player | null>(null);
const form = reactive({ name: '', contactType: '微信', contact: '', gender: '男', status: 'available' as Player['status'], capabilities: [{ mode: '机密', tier: '娱乐陪' }] as Capability[], notes: '' });
const isAdmin = computed(() => state.user?.role === 'admin');
const selected = computed(() => state.players.find(p => p.id === detailId.value));
const availableCount = computed(() => state.players.filter(p => p.status === 'available').length);
const servingCount = computed(() => new Set(state.orders.flatMap(o => o.assignments.filter(a => a.status === 'serving').map(a => a.playerId))).size);
const filteredPlayers = computed(() => state.players.filter(p => {
  const term = search.value.trim().toLowerCase();
  const textMatch = !term || `${p.name} ${p.code} ${p.contact} ${p.notes}`.toLowerCase().includes(term);
  const capabilityMatch = !modeFilter.value && !tierFilter.value || p.capabilities.some(c => (!modeFilter.value || c.mode === modeFilter.value) && (!tierFilter.value || c.tier === tierFilter.value));
  return textMatch && capabilityMatch && (!statusFilter.value || p.status === statusFilter.value);
}));
type AssignmentRow = { assignment: Assignment; order: Order };
const assignmentRows = computed<AssignmentRow[]>(() => state.orders.flatMap(order => order.assignments.filter(assignment => assignment.playerId === detailId.value).map(assignment => ({ assignment, order }))));
const selectedEarnings = computed(() => assignmentRows.value.reduce((sum, row) => sum + (row.assignment.earningCents || 0), 0));
const unsettledEarnings = computed(() => assignmentRows.value.filter(row => !row.assignment.settled).reduce((sum, row) => sum + (row.assignment.earningCents || 0), 0));
const serviceHours = computed(() => assignmentRows.value.filter(row => row.assignment.status === 'completed' || row.assignment.status === 'replaced').reduce((sum, row) => {
  const a = row.assignment;
  return sum + (a.startedAt && a.endedAt ? Math.max(0, new Date(a.endedAt).getTime() - new Date(a.startedAt).getTime()) / 3600000 : 0);
}, 0));

function statusLabel(status: Player['status']) { return ({ available: '可接单', resting: '休息中', disabled: '已停用' } as const)[status]; }
function statusTone(status: Player['status']) { return status === 'available' ? 'success' : 'info'; }
function assignmentLabel(status: Assignment['status']) { return ({ assigned: '待服务', serving: '服务中', completed: '已完成', replaced: '已换人', cancelled: '已取消' } as const)[status]; }
function dateTime(value?: string) { return value ? new Date(value).toLocaleString('zh-CN', { hour12: false, timeZone: 'Asia/Shanghai' }) : '—'; }
function activeArrangements(playerId: string) {
  return state.orders.filter(o => o.status === 'paid').flatMap(order => order.assignments.filter(a => a.playerId === playerId && ['assigned', 'serving'].includes(a.status)).map(assignment => ({ assignment, order, item: order.items.find(i => i.id === assignment.itemId) })));
}
function openEditor(player?: Player) {
  editing.value = player || null;
  Object.assign(form, player ? { name: player.name, contactType: player.contactType, contact: player.contact, gender: player.gender, status: player.status, capabilities: player.capabilities.map(c => ({ ...c })), notes: player.notes } : { name: '', contactType: '微信', contact: '', gender: '男', status: 'available', capabilities: [{ mode: '机密', tier: '娱乐陪' }], notes: '' });
  editorOpen.value = true;
}
function addCapability() { form.capabilities.push({ mode: '机密', tier: '娱乐陪' }); }
async function savePlayer() {
  if (!form.name.trim() || !form.contact.trim()) { ElMessage.warning('请填写陪玩昵称和内部联系方式'); return; }
  if (!form.capabilities.length) { ElMessage.warning('请至少登记一组服务模式与档位'); return; }
  const keys = form.capabilities.map(c => `${c.mode}-${c.tier}`);
  if (new Set(keys).size !== keys.length) { ElMessage.warning('服务能力中存在重复的模式与档位，请合并后保存'); return; }
  busy.value = true;
  try {
    await api(editing.value ? `/api/players/${editing.value.id}` : '/api/players', { method: editing.value ? 'PUT' : 'POST', body: JSON.stringify({ ...form, name: form.name.trim(), contact: form.contact.trim(), capabilities: form.capabilities.map(c => ({ ...c })), ...(editing.value ? { version: editing.value.version } : {}) }) });
    await refresh(); editorOpen.value = false; ElMessage.success(editing.value ? '陪玩资料已更新' : '陪玩成员已录入，可以开始派单');
  } catch (error) { notifyError(error); } finally { busy.value = false; }
}
function showDetail(player: Player) { detailId.value = player.id; detailTab.value = 'capabilities'; detailOpen.value = true; }
async function download(format: 'xlsx' | 'csv' = 'xlsx') { try { await exportFile('players', format); } catch (error) { notifyError(error); } }
</script>

<template>
  <div class="players-page">
    <div class="page-head"><div><h1 class="page-title">陪玩成员</h1><p class="page-subtitle">按模式与档位维护服务能力，为每条订单安排合适的人选。</p></div><el-button v-if="can('players')" type="primary" size="large" @click="openEditor()">＋ 录入陪玩</el-button></div>
    <div class="player-summary"><div><span class="summary-mark purple">陪</span><section><small>在册陪玩</small><strong>{{ state.players.length }}<em> 位</em></strong></section></div><div><span class="summary-mark green">闲</span><section><small>可接单成员</small><strong>{{ availableCount }}<em> 位</em></strong></section></div><div><span class="summary-mark amber">服</span><section><small>正在服务</small><strong>{{ servingCount }}<em> 位</em></strong></section></div></div>
    <div class="panel members-panel">
      <div class="toolbar"><el-input v-model="search" clearable placeholder="搜索昵称、编号或联系方式" class="search-input" /><el-select v-model="statusFilter" clearable placeholder="全部接单状态" class="filter-select"><el-option label="可接单" value="available" /><el-option label="休息中" value="resting" /><el-option label="已停用" value="disabled" /></el-select><el-select v-model="modeFilter" clearable placeholder="全部模式" class="mode-select"><el-option v-for="mode in modes" :key="mode" :label="mode" :value="mode" /></el-select><el-select v-model="tierFilter" clearable placeholder="全部档位" class="filter-select"><el-option v-for="tier in tiers" :key="tier" :label="tier" :value="tier" /></el-select><span class="toolbar-spacer" /><el-button v-if="can('export')" @click="download()">导出 Excel</el-button></div>
      <div class="member-panel-head"><strong>成员档案 <span>{{ filteredPlayers.length }}</span></strong><span class="muted">联系方式与内部备注仅在后台展示</span></div>
      <el-table :data="filteredPlayers" row-key="id" empty-text="还没有符合条件的成员，录入陪玩后即可在订单中派单" @row-dblclick="showDetail">
        <el-table-column label="陪玩成员" min-width="165"><template #default="{ row }"><div class="person-cell"><span class="player-avatar" :class="row.gender === '女' ? 'rose' : row.gender === '男' ? '' : 'neutral'">{{ row.name.slice(0, 1) }}</span><div><button class="text-link" @click="showDetail(row)">{{ row.name }}<PlayerGender :gender="row.gender" compact class="name-gender" /></button><small>{{ row.code }}</small></div></div></template></el-table-column>
        <el-table-column label="服务能力" min-width="280"><template #default="{ row }"><div class="capability-tags"><span v-for="capability in row.capabilities" :key="`${capability.mode}-${capability.tier}`" :class="capability.mode === '绝密' ? 'absolute' : ''">{{ capability.mode }} · {{ capability.tier }}</span></div></template></el-table-column>
        <el-table-column label="接单状态" min-width="105"><template #default="{ row }"><el-tag :type="statusTone(row.status)" size="small" effect="light">{{ statusLabel(row.status) }}</el-tag></template></el-table-column>
        <el-table-column label="当前安排" min-width="180"><template #default="{ row }"><template v-if="activeArrangements(row.id).length"><div v-for="arrangement in activeArrangements(row.id).slice(0, 2)" :key="arrangement.assignment.id" class="arrangement"><i :class="arrangement.assignment.status === 'serving' ? 'serving' : ''" /><span>{{ arrangement.order.customerName }} · {{ assignmentLabel(arrangement.assignment.status) }}</span></div><span v-if="activeArrangements(row.id).length > 2" class="muted tiny">另有 {{ activeArrangements(row.id).length - 2 }} 条安排</span></template><span v-else class="muted">暂无进行中的安排</span></template></el-table-column>
        <el-table-column label="内部联系方式" min-width="160"><template #default="{ row }"><div>{{ row.contact }}</div><span class="muted tiny">{{ row.contactType }}</span></template></el-table-column>
        <el-table-column label="操作" min-width="125" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="showDetail(row)">详情</el-button><el-button v-if="can('players')" link @click="openEditor(row)">编辑</el-button></template></el-table-column>
      </el-table>
    </div>

    <el-drawer v-model="editorOpen" :title="editing ? '编辑陪玩成员' : '录入陪玩成员'" size="min(580px, 96vw)" :close-on-click-modal="!busy">
      <p class="drawer-intro">服务能力按“模式＋档位”逐条登记，派单时会按订单要求匹配。</p>
      <el-form :model="form" label-position="top" @submit.prevent>
        <div class="form-grid"><el-form-item label="陪玩昵称" required><el-input v-model="form.name" maxlength="40" placeholder="客服与客户使用的昵称" /></el-form-item><el-form-item label="性别"><el-select v-model="form.gender"><el-option label="男" value="男" /><el-option label="女" value="女" /><el-option label="其他 / 未登记" value="其他" /></el-select></el-form-item></div>
        <div class="form-grid contact-grid"><el-form-item label="联系类型"><el-select v-model="form.contactType"><el-option v-for="type in ['微信', 'QQ', '手机号', '其他']" :key="type" :label="type" :value="type" /></el-select></el-form-item><el-form-item label="内部联系号码" required><el-input v-model="form.contact" maxlength="80" placeholder="仅后台可见" /></el-form-item></div>
        <el-form-item label="接单状态" class="status-form-item"><el-radio-group v-model="form.status"><el-radio-button value="available">可接单</el-radio-button><el-radio-button value="resting">休息中</el-radio-button><el-radio-button value="disabled">停用</el-radio-button></el-radio-group><div class="muted tiny status-tip">休息或停用后不会作为正常派单候选，历史服务记录保留。</div></el-form-item>
        <div class="capability-editor"><div class="section-heading"><label>服务能力 <span>*</span></label><el-button link type="primary" @click="addCapability">＋ 添加能力</el-button></div><div v-for="(capability, index) in form.capabilities" :key="index" class="capability-row"><span class="capability-number">{{ String(index + 1).padStart(2, '0') }}</span><el-select v-model="capability.mode" placeholder="模式"><el-option v-for="mode in modes" :key="mode" :label="mode" :value="mode" /></el-select><el-select v-model="capability.tier" placeholder="档位"><el-option v-for="tier in tiers" :key="tier" :label="tier" :value="tier" /></el-select><el-button link type="danger" :disabled="form.capabilities.length <= 1" @click="form.capabilities.splice(index, 1)">移除</el-button></div><p class="muted tiny">例如同时登记“机密·技术陪”和“绝密·娱乐陪”，不会被自动视为可接“绝密·技术陪”。</p></div>
        <el-form-item label="内部备注"><el-input v-model="form.notes" type="textarea" :rows="4" maxlength="1000" show-word-limit placeholder="擅长内容、常见在线时段、派单注意事项等" /></el-form-item>
      </el-form>
      <template #footer><el-button :disabled="busy" @click="editorOpen = false">取消</el-button><el-button type="primary" :loading="busy" @click="savePlayer">保存成员档案</el-button></template>
    </el-drawer>

    <el-drawer v-model="detailOpen" title="陪玩成员档案" size="min(1000px, 97vw)">
      <template v-if="selected"><div class="detail-hero"><span class="player-avatar large" :class="selected.gender === '女' ? 'rose' : selected.gender === '男' ? '' : 'neutral'">{{ selected.name.slice(0, 1) }}</span><div><h2>{{ selected.name }} <PlayerGender :gender="selected.gender" /><el-tag :type="statusTone(selected.status)" size="small">{{ statusLabel(selected.status) }}</el-tag></h2><p>{{ selected.code }} · {{ selected.gender }} · {{ selected.contactType }} {{ selected.contact }}</p></div><el-button v-if="can('players')" class="hero-edit" @click="openEditor(selected)">编辑资料</el-button></div>
        <div class="detail-stats"><div><strong>{{ assignmentRows.length }}<small> 条</small></strong><span>累计派单记录</span></div><div><strong>{{ serviceHours.toFixed(1) }}<small> 小时</small></strong><span>已登记实际服务</span></div><div v-if="isAdmin"><strong>{{ money(selectedEarnings) }}</strong><span>人工登记应得合计</span></div><div v-if="isAdmin"><strong>{{ money(unsettledEarnings) }}</strong><span>尚未登记结算</span></div></div>
        <el-tabs v-model="detailTab"><el-tab-pane label="服务能力与资料" name="capabilities"><h3 class="section-title">可接服务组合</h3><div class="capability-detail"><div v-for="capability in selected.capabilities" :key="`${capability.mode}-${capability.tier}`"><span class="mode-badge" :class="capability.mode === '绝密' ? 'absolute' : ''">{{ capability.mode }}</span><strong>{{ capability.tier }}</strong><span class="muted">{{ money(state.settings?.prices?.[capability.mode]?.[capability.tier] || 0) }} / 小时基础价</span></div></div><el-descriptions :column="2" border class="profile-descriptions"><el-descriptions-item label="联系类型">{{ selected.contactType }}</el-descriptions-item><el-descriptions-item label="内部联系方式">{{ selected.contact }}</el-descriptions-item><el-descriptions-item label="创建时间">{{ dateTime(selected.createdAt) }}</el-descriptions-item><el-descriptions-item label="最近更新">{{ dateTime(selected.updatedAt) }}</el-descriptions-item><el-descriptions-item label="内部备注" :span="2">{{ selected.notes || '暂无备注' }}</el-descriptions-item></el-descriptions><h3 class="section-title arrange-title">当前服务与预约</h3><el-empty v-if="!activeArrangements(selected.id).length" description="暂无待服务或进行中的订单" :image-size="65" /><div v-for="arrangement in activeArrangements(selected.id)" :key="arrangement.assignment.id" class="arrangement-card"><div><el-tag size="small" :type="arrangement.assignment.status === 'serving' ? 'success' : 'warning'">{{ assignmentLabel(arrangement.assignment.status) }}</el-tag><strong>{{ arrangement.order.customerName }}</strong><span>{{ arrangement.item?.mode }} · {{ arrangement.item?.tier }} · {{ arrangement.item?.hours }}小时</span></div><p>预约：{{ dateTime(arrangement.item?.plannedStart) }}</p><el-button link type="primary" @click="router.push({ path: '/orders', query: { orderId: arrangement.order.id } })">{{ arrangement.order.code }} →</el-button></div></el-tab-pane>
          <el-tab-pane label="历史派单与服务" name="assignments"><el-table :data="assignmentRows" empty-text="暂无派单记录"><el-table-column label="订单 / 客户" min-width="190"><template #default="{ row }"><el-button link type="primary" @click="router.push({ path: '/orders', query: { orderId: row.order.id } })">{{ row.order.code }}</el-button><div class="muted tiny">{{ row.order.customerName }}</div></template></el-table-column><el-table-column label="服务内容" min-width="140"><template #default="{ row }">{{ row.order.items.find((i: any) => i.id === row.assignment.itemId)?.mode }} · {{ row.order.items.find((i: any) => i.id === row.assignment.itemId)?.tier }}</template></el-table-column><el-table-column label="状态" min-width="95"><template #default="{ row }"><el-tag :type="row.assignment.status === 'serving' ? 'success' : 'info'" size="small">{{ assignmentLabel(row.assignment.status) }}</el-tag></template></el-table-column><el-table-column label="开始 / 结束" min-width="170"><template #default="{ row }"><div>{{ dateTime(row.assignment.startedAt) }}</div><div class="muted tiny">{{ dateTime(row.assignment.endedAt) }}</div></template></el-table-column><el-table-column label="补时 / 原因" min-width="180"><template #default="{ row }"><div v-if="row.assignment.freeMinutes">免费补时 {{ row.assignment.freeMinutes }} 分钟</div><span class="muted tiny">{{ row.assignment.freeReason || row.assignment.reason || '—' }}</span></template></el-table-column></el-table></el-tab-pane>
          <el-tab-pane v-if="isAdmin" label="应得与结算记录" name="earnings"><el-alert title="成员应得金额由管理人员在订单服务记录中登记，此处汇总；结算状态仅为人工登记，不发起实际付款。" type="info" :closable="false" show-icon class="earning-alert" /><el-table :data="assignmentRows" empty-text="暂无应得记录"><el-table-column label="订单" min-width="180"><template #default="{ row }"><el-button link type="primary" @click="router.push({ path: '/orders', query: { orderId: row.order.id } })">{{ row.order.code }}</el-button></template></el-table-column><el-table-column prop="order.customerName" label="客户" min-width="120" /><el-table-column label="应得金额" min-width="130" align="right"><template #default="{ row }"><strong class="money">{{ money(row.assignment.earningCents || 0) }}</strong></template></el-table-column><el-table-column label="结算登记" min-width="120"><template #default="{ row }"><el-tag size="small" :type="row.assignment.settled ? 'success' : 'warning'">{{ row.assignment.settled ? '已登记结算' : '待登记结算' }}</el-tag></template></el-table-column><el-table-column label="派单时间" min-width="170"><template #default="{ row }">{{ dateTime(row.assignment.assignedAt) }}</template></el-table-column></el-table></el-tab-pane>
        </el-tabs>
      </template><el-empty v-else description="未找到成员档案" />
    </el-drawer>
  </div>
</template>

<style scoped>
